      if (state.fail) throw new Error('Failed to connect to Bridge: ECONNREFUSED');
      return {
        status: 200,
        responseText: JSON.stringify({
          ok: true,
          project_id: state.projectId,
          filename: state.filename,
          mtime: Math.floor(state.mtime / 1000)
        })
      };
    }
    return { status: 404 };
  };
}

